package com.bank.eventstorming.account;

import java.math.BigDecimal;
import java.util.logging.Logger;

// SMALL aggregate root. Enforces its OWN invariant (balance >= 0).
// Carries a version for optimistic locking (the @Version column).
public class Account {
    private static final Logger log = Logger.getLogger(Account.class.getName());
    private final String accountId;
    private BigDecimal balance;
    private long version;

    public Account(String accountId, BigDecimal balance) {
        this.accountId = accountId; this.balance = balance; this.version = 0;
    }

    public void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0)
            throw new IllegalStateException("Insufficient funds in " + accountId);
        balance = balance.subtract(amount);
        version++;                       // every change bumps the version
    }
    public void credit(BigDecimal amount) { balance = balance.add(amount); version++; }

    // Optimistic lock check: fails if another writer already advanced the version.
    public void assertVersion(long expected) {
        if (version != expected) {
            log.severe("Version conflict on " + accountId
                     + " expected " + expected + " but was " + version);
            throw new IllegalStateException("OptimisticLockException on " + accountId);
        }
    }
    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public long getVersion() { return version; }
}
