package com.bank.eventstorming.transfer;

import java.math.BigDecimal;

// Transfer aggregate. References other aggregates by ID ONLY (never by object).
public class Transfer {
    private final String transferId;
    private final String fromAccountId;   // ID, not an Account object
    private final String toAccountId;     // ID, not an Account object
    private final BigDecimal amount;
    private String status = "INITIATED";

    public Transfer(String transferId, String fromAccountId, String toAccountId, BigDecimal amount) {
        this.transferId = transferId;
        this.fromAccountId = fromAccountId;
        this.toAccountId = toAccountId;
        this.amount = amount;
    }
    public void markCompleted() { this.status = "COMPLETED"; }
    public void markFailed() { this.status = "FAILED"; }
    public String getFromAccountId() { return fromAccountId; }
    public String getToAccountId() { return toAccountId; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }
}
