package com.bank.eventstorming.saga;

import com.bank.eventstorming.account.Account;
import com.bank.eventstorming.transfer.Transfer;
import java.util.logging.Level;
import java.util.logging.Logger;

// Cross-aggregate work is a SAGA, not one transaction, because each
// Account is its own consistency boundary.
public class TransferSaga {
    private static final Logger log = Logger.getLogger(TransferSaga.class.getName());

    public void execute(Transfer transfer, Account from, Account to) {
        try {
            from.debit(transfer.getAmount());    // modifies ONLY the 'from' aggregate
            to.credit(transfer.getAmount());     // modifies ONLY the 'to' aggregate
            transfer.markCompleted();
            log.info(() -> "Transfer COMPLETED " + transfer.getFromAccountId()
                         + " → " + transfer.getToAccountId());
        } catch (IllegalStateException ex) {
            log.log(Level.SEVERE, "Transfer failed — compensating", ex);
            transfer.markFailed();
        }
    }
}
