package com.bank.eventstorming;

import com.bank.eventstorming.account.Account;
import com.bank.eventstorming.saga.TransferSaga;
import com.bank.eventstorming.transfer.Transfer;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class EventStormingDemo {
    private static final Logger log = Logger.getLogger(EventStormingDemo.class.getName());

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", new BigDecimal("250000"));
        TransferSaga saga = new TransferSaga();

        log.info("=== Small aggregates: transfer across two accounts (saga) ===");
        Transfer t1 = new Transfer("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000"));
        saga.execute(t1, rajesh, priya);
        log.info("Rajesh=" + rajesh.getBalance() + " v" + rajesh.getVersion()
               + ", Priya=" + priya.getBalance() + " v" + priya.getVersion());

        log.info("=== Optimistic lock conflict on the SAME account ===");
        long staleVersion = rajesh.getVersion();   // reader A snapshot
        rajesh.debit(new BigDecimal("10000"));      // writer B commits first → version++
        try {
            rajesh.assertVersion(staleVersion);     // writer A now stale → conflict
        } catch (IllegalStateException ex) {
            log.warning("Retrying with fresh version " + rajesh.getVersion());
        }
    }
}
